def validate_transition(workflow_dag: dict, current: str, target: str, payload: dict) -> None:
    allowed = workflow_dag.get(current, {})
    if target not in allowed:
        raise PermissionError(f'Transition {current} -> {target} not permitted')
    for req_field in allowed[target].get('required_fields', []):
        if not payload.get(req_field):
            raise ValueError(f'Missing required field: {req_field}')

def reorder_issue(pg, board_id, issue_id, target_status, left_rank, right_rank, version):
    new_rank = lexo_midpoint(left_rank, right_rank)
    rows = pg.execute(
        'UPDATE issues SET status=%s, rank=%s, version=version+1 '
        'WHERE id=%s AND board_id=%s AND version=%s RETURNING version',
        (target_status, new_rank, issue_id, board_id, version)
    )
    if not rows:
        raise ConflictError('Stale issue version; refresh board state')
    return new_rank, rows[0]['version']

def create_presigned_upload(s3_client, bucket: str, tenant_id: str, filename: str) -> dict:
    key = f'tenants/{tenant_id}/uploads/{uuid.uuid4()}/{filename}'
    return s3_client.generate_presigned_post(Bucket=bucket, Key=key, ExpiresIn=300,
                                             Conditions=[['content-length-range', 1, 52428800]])

def fetch_board_page(conn, board_id: str, cursor_rank: str = '0|000000:', limit: int = 100):
    return conn.execute(
        'SELECT id, key, summary, status, rank, version FROM issues '
        'WHERE board_id=%s AND archived_at IS NULL AND rank > %s '
        'ORDER BY rank ASC LIMIT %s',
        (board_id, cursor_rank, limit)
    )
